/**
 * Incoming request-ID validation.
 *
 * Security model
 * ══════════════
 * Upstream services (reverse proxies, API gateways, other microservices) may
 * forward a pre-assigned request identifier in a header such as X-Request-ID.
 * Blindly trusting that value is dangerous:
 *
 *   • Header injection — a crafted value could break log parsers or corrupt
 *     structured-logging pipelines.
 *   • Oversized values — an attacker could send arbitrarily long strings to
 *     exhaust memory in log aggregation systems.
 *   • Log forging — allowing free-text IDs lets attackers inject fake log
 *     lines that look like legitimate request IDs from other services.
 *
 * We validate with an allowlist (not a denylist) approach:
 *   - Maximum byte length cap (default 128 chars)
 *   - Character allowlist: alphanumeric, hyphens, underscores, dots, colons
 *   - Non-empty check
 *
 * Trusted-proxy note
 * ══════════════════
 * `useIncoming` should only be enabled when the Express app sits behind a
 * reverse proxy you control (nginx, AWS ALB, Cloudflare, etc.).  When
 * traffic comes directly from untrusted clients, prefer `useIncoming: false`
 * and let this middleware generate a fresh ID for every request.
 */

import {
  MAX_INCOMING_ID_LENGTH,
  INCOMING_ID_PATTERN,
} from "../config/defaults.js";

/**
 * Validate an incoming request-ID string.
 *
 * @param {unknown}  id      - The raw header value.
 * @param {object}  [opts]
 * @param {number}  [opts.maxLength=128]           - Maximum allowed length.
 * @param {RegExp}  [opts.pattern=INCOMING_ID_PATTERN] - Allowlist pattern.
 * @returns {{ valid: boolean; reason?: string }}
 */
export function validateRequestId(id, opts = {}) {
  const maxLength = opts.maxLength ?? MAX_INCOMING_ID_LENGTH;
  const pattern   = opts.pattern   ?? INCOMING_ID_PATTERN;

  if (typeof id !== "string") {
    return { valid: false, reason: "not a string" };
  }

  if (id.length === 0) {
    return { valid: false, reason: "empty string" };
  }

  if (id.length > maxLength) {
    return {
      valid:  false,
      reason: `exceeds max length (${id.length} > ${maxLength})`,
    };
  }

  if (!pattern.test(id)) {
    return { valid: false, reason: "contains disallowed characters" };
  }

  return { valid: true };
}
